#include <iostream>
#include <vector>
#include <iterator>

// Template function accepting a const vector reference
template <typename T>
void printForward(const std::vector<T>& vec) {
    std::cout << "Forward (cbegin/cend): ";
    for (auto it = vec.cbegin(); it != vec.cend(); ++it) {
        std::cout << *it << ' ';
    }
    std::cout << "\n";
}

int main() {
    // Built-in array traversal with pointer iterators
    const size_t SIZE = 6;
    int rawArr[SIZE] = {1, 2, 3, 4, 5, 6};

    std::cout << "Built-in array using std::begin/end pointers: ";
    for (const int* ptr = std::begin(rawArr); ptr != std::end(rawArr); ++ptr) {
        std::cout << *ptr << ' ';
    }
    std::cout << "\n";

    // Create and populate vector
    std::vector<int> integers;
    integers.push_back(2);
    integers.push_back(3);
    integers.push_back(4);

    printForward(integers);

    // Reverse traversal using const_reverse_iterator
    std::cout << "Reversed (crbegin/crend): ";
    for (auto rIt = integers.crbegin(); rIt != integers.crend(); ++rIt) {
        std::cout << *rIt << ' ';
    }
    std::cout << "\n";

    return 0;
}
